<script setup>import{ref,onMounted,nextTick}from'vue';import*as echarts from'echarts/core';import{LineChart}from'echarts/charts';import{GridComponent,TooltipComponent}from'echarts/components';import{CanvasRenderer}from'echarts/renderers';import{api}from'../api';echarts.use([LineChart,GridComponent,TooltipComponent,CanvasRenderer]);const data=ref({sales:0,orders:0,verifications:0,members:0,todayNewMembers:0}),chart=ref();onMounted(async()=>{const[r,s]=await Promise.all([api.overview(),api.sales()]);data.value=r;await nextTick();const c=echarts.init(chart.value);c.setOption({grid:{left:45,right:20,top:32,bottom:35},tooltip:{trigger:'axis'},xAxis:{type:'category',data:s.map(x=>x.date),axisLine:{lineStyle:{color:'#d7e3de'}}},yAxis:{type:'value',splitLine:{lineStyle:{color:'#edf2f0'}}},series:[{name:'实收销售额',type:'line',smooth:true,data:s.map(x=>x.amount),symbolSize:7,lineStyle:{width:3,color:'#246c59'},itemStyle:{color:'#d0a95f'},areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'#4b8d7a55'},{offset:1,color:'#4b8d7a05'}])}}]});addEventListener('resize',()=>c.resize())})</script>
<template><div class="page-head"><div><h2>今日经营概览</h2><p>按已支付订单实收金额统计，数据实时更新</p></div><el-tag type="success" effect="plain">系统运行中</el-tag></div><div class="cards"><div class="metric"><small>累计销售额</small><strong>¥ {{data.sales}}</strong><em>微信与现金合计</em></div><div class="metric"><small>售卡订单</small><strong>{{data.orders}}</strong><em>已支付订单</em></div><div class="metric"><small>累计核销</small><strong>{{data.verifications}}</strong><em>现场使用记录</em></div><div class="metric"><small>会员总数</small><strong>{{data.members}}</strong><em>今日新增 {{data.todayNewMembers}}</em></div></div><div class="panel chart"><div style="font-weight:700">销售趋势</div><div ref="chart" style="height:310px"></div></div></template>
